```html id="rtac-clean"
<section>
  <style>
    .rt-tac {
      --rt-bg: #061423;
      --rt-bg-2: #0a1d31;
      --rt-card: #0d2138;
      --rt-card-2: #132c48;
      --rt-orange: #f09a37;
      --rt-orange-2: #ffb65c;
      --rt-muted: #b8c6d8;
      --rt-text: #eaf1f8;
      font-family: inherit;
      color: var(--rt-text);
      overflow-x: hidden;
      background: var(--rt-bg);
    }
    .rt-tac,
    .rt-tac * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }
    .rt-tac a {
      color: var(--rt-orange);
      text-decoration: none;
    }
    .rt-tac a:hover {
      color: var(--rt-orange-2);
      text-decoration: underline;
    }
    .rt-tac .rtac-wrap {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 28px;
    }
    .rt-tac .rtac-gridbg {
      position: absolute;
      inset: 0;
      background-image:
        linear-gradient(rgba(255, 255, 255, 0.026) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255, 255, 255, 0.026) 1px, transparent 1px);
      background-size: 42px 42px;
      -webkit-mask-image: linear-gradient(180deg, transparent, rgba(0, 0, 0, 0.5) 14%, rgba(0, 0, 0, 0.5) 80%, transparent);
      mask-image: linear-gradient(180deg, transparent, rgba(0, 0, 0, 0.5) 14%, rgba(0, 0, 0, 0.5) 80%, transparent);
      pointer-events: none;
    }
    .rt-tac .rtac-eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      border: 1px solid rgba(240, 154, 55, 0.28);
      background: rgba(240, 154, 55, 0.1);
      border-radius: 999px;
      padding: 6px 16px 6px 10px;
      font-size: 0.8rem;
      font-weight: 900;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--rt-orange-2);
      margin-bottom: 22px;
    }
    .rt-tac .rtac-eyebrow::before {
      content: "";
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: var(--rt-orange);
      box-shadow: 0 0 8px var(--rt-orange);
      animation: rtac-pulse 2s ease-in-out infinite;
    }
    @keyframes rtac-pulse {
      0%,
      100% {
        opacity: 1;
        transform: scale(1);
      }
      50% {
        opacity: 0.5;
        transform: scale(0.8);
      }
    }
    .rt-tac .rtac-btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      border-radius: 999px;
      font-weight: 900;
      font-size: 1rem;
      padding: 14px 32px;
      text-decoration: none !important;
      cursor: pointer;
      border: none;
      transition: all 0.25s ease;
    }
    .rt-tac .rtac-btn.primary {
      background: linear-gradient(135deg, var(--rt-orange), var(--rt-orange-2));
      color: #071423 !important;
      box-shadow: 0 4px 24px rgba(240, 154, 55, 0.35);
      position: relative;
      overflow: hidden;
    }
    .rt-tac .rtac-btn.primary::after {
      content: "";
      position: absolute;
      top: -50%;
      left: -60%;
      width: 40%;
      height: 200%;
      background: rgba(255, 255, 255, 0.18);
      transform: skewX(-20deg);
      animation: rtac-shine 3.5s ease-in-out infinite;
    }
    @keyframes rtac-shine {
      0% {
        left: -60%;
      }
      60%,
      100% {
        left: 130%;
      }
    }
    .rt-tac .rtac-btn.secondary {
      background: rgba(255, 255, 255, 0.06);
      color: #fff !important;
      border: 1px solid rgba(255, 255, 255, 0.16);
      backdrop-filter: blur(14px);
    }
    .rt-tac .rtac-btn.secondary:hover {
      background: rgba(255, 255, 255, 0.12);
    }
    @keyframes rtac-float {
      0%,
      100% {
        transform: translateY(0);
      }
      50% {
        transform: translateY(-12px);
      }
    }
    .rt-tac .rtac-hero {
      position: relative;
      min-height: 720px;
      display: flex;
      align-items: center;
      background:
        radial-gradient(circle at 80% 10%, rgba(240, 154, 55, 0.13), transparent 28%),
        linear-gradient(135deg, #04111d, #07192b, #091c2f);
      padding: 76px 0 88px;
      overflow: hidden;
    }
    .rt-tac .rtac-hero-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 56px;
      align-items: center;
    }
    .rt-tac .rtac-hero h1 {
      font-size: clamp(38px, 5.5vw, 78px);
      font-weight: 950;
      letter-spacing: -0.07em;
      line-height: 0.94;
      margin-bottom: 22px;
      color: #fff;
    }
    .rt-tac .rtac-hero h1 span {
      background: linear-gradient(135deg, var(--rt-orange), var(--rt-orange-2) 50%, #fff);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }
    .rt-tac .rtac-hero p {
      font-size: 1.1rem;
      color: var(--rt-muted);
      line-height: 1.65;
      max-width: 480px;
      margin-bottom: 30px;
    }
    .rt-tac .rtac-hero-btns {
      display: flex;
      gap: 14px;
      flex-wrap: wrap;
    }
    .rt-tac .rtac-hero-right {
      position: relative;
    }
    .rt-tac .rtac-hero-img-wrap {
      border-radius: 32px;
      overflow: hidden;
      border: 1px solid rgba(255, 255, 255, 0.1);
      box-shadow: 0 0 60px rgba(240, 154, 55, 0.15);
      animation: rtac-float 6s ease-in-out infinite;
    }
    .rt-tac .rtac-hero-img-wrap img {
      width: 100%;
      display: block;
      height: 380px;
      object-fit: cover;
    }
    .rt-tac .rtac-stat-card {
      position: absolute;
      bottom: -24px;
      left: -28px;
      background: linear-gradient(135deg, #132c48, #0d2138);
      border: 1px solid rgba(240, 154, 55, 0.22);
      border-radius: 20px;
      padding: 18px 24px;
      box-shadow: 0 20px 60px rgba(0, 0, 0, 0.4);
    }
    .rt-tac .rtac-stat-num {
      font-size: 2rem;
      font-weight: 950;
      letter-spacing: -0.05em;
      color: var(--rt-orange);
      line-height: 1;
    }
    .rt-tac .rtac-stat-label {
      font-size: 0.78rem;
      color: var(--rt-muted);
      text-transform: uppercase;
      letter-spacing: 0.06em;
      margin-top: 4px;
    }
    .rt-tac .rtac-qnav {
      position: relative;
      z-index: 5;
      margin-top: -44px;
      padding-bottom: 60px;
    }
    .rt-tac .rtac-qnav-box {
      background: linear-gradient(180deg, #132c48, #0d2138);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 24px;
      overflow: hidden;
      box-shadow: 0 28px 80px rgba(0, 0, 0, 0.34);
    }
    .rt-tac .rtac-qnav-inner {
      display: grid;
      grid-template-columns: 0.78fr 1fr;
      min-height: 120px;
    }
    .rt-tac .rtac-qnav-left {
      padding: 28px 32px;
      border-right: 1px solid rgba(255, 255, 255, 0.08);
    }
    .rt-tac .rtac-qnav-left h2 {
      font-size: 1.3rem;
      font-weight: 900;
      letter-spacing: -0.03em;
      margin-bottom: 6px;
      color: #fff;
    }
    .rt-tac .rtac-qnav-left p {
      font-size: 0.88rem;
      color: var(--rt-muted);
    }
    .rt-tac .rtac-qnav-links {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 0;
    }
    .rt-tac .rtac-qnav-link {
      display: block;
      padding: 18px 24px;
      border-right: 1px solid rgba(255, 255, 255, 0.06);
      border-bottom: 1px solid rgba(255, 255, 255, 0.06);
      transition: background 0.2s ease;
    }
    .rt-tac .rtac-qnav-link:hover {
      background: rgba(240, 154, 55, 0.06);
    }
    .rt-tac .rtac-qnav-link strong {
      display: block;
      font-size: 0.9rem;
      font-weight: 700;
      margin-bottom: 2px;
      color: #fff;
    }
    .rt-tac .rtac-qnav-link span {
      font-size: 0.8rem;
      color: var(--rt-orange);
    }
    .rt-tac .rtac-stats {
      padding: 40px 0 80px;
    }
    .rt-tac .rtac-stats-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 20px;
    }
    .rt-tac .rtac-stat-box {
      background: linear-gradient(180deg, #132c48, #0d2138);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 20px;
      padding: 28px 24px;
    }
    .rt-tac .rtac-stat-big {
      font-size: 2.5rem;
      font-weight: 950;
      color: var(--rt-orange);
      letter-spacing: -0.05em;
      line-height: 1;
    }
    .rt-tac .rtac-stat-title {
      font-size: 0.78rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.07em;
      margin: 8px 0 4px;
      color: #fff;
    }
    .rt-tac .rtac-stat-desc {
      font-size: 0.82rem;
      color: var(--rt-muted);
    }
    .rt-tac .rtac-main {
      padding: 100px 0;
      background:
        radial-gradient(circle at 10% 50%, rgba(240, 154, 55, 0.07), transparent 40%),
        #0a1d31;
    }
    .rt-tac .rtac-main-head {
      display: grid;
      grid-template-columns: 0.9fr 1.1fr;
      gap: 48px;
      align-items: start;
      margin-bottom: 64px;
    }
    .rt-tac .rtac-main h2 {
      font-size: clamp(32px, 4vw, 52px);
      font-weight: 950;
      letter-spacing: -0.05em;
      line-height: 1.04;
      color: #fff;
    }
    .rt-tac .rtac-main-desc {
      font-size: 1rem;
      color: var(--rt-muted);
      line-height: 1.7;
      padding-top: 8px;
    }
    .rt-tac .rtac-features {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 16px;
    }
    .rt-tac .rtac-feature {
      background: linear-gradient(180deg, #132c48, #0d2138);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 20px;
      padding: 24px 20px;
      transition: transform 0.25s ease, border-color 0.25s ease;
    }
    .rt-tac .rtac-feature:hover {
      transform: translateY(-4px);
      border-color: rgba(240, 154, 55, 0.25);
    }
    .rt-tac .rtac-feature-num {
      width: 34px;
      height: 34px;
      background: var(--rt-orange);
      border-radius: 8px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 0.75rem;
      font-weight: 900;
      color: #071423;
      margin-bottom: 14px;
    }
    .rt-tac .rtac-feature h3 {
      font-size: 0.95rem;
      font-weight: 700;
      margin-bottom: 8px;
      color: #fff;
    }
    .rt-tac .rtac-feature p {
      font-size: 0.82rem;
      color: var(--rt-muted);
      line-height: 1.55;
    }
    .rt-tac .rtac-tabs-sec {
      padding: 100px 0;
      background: #061423;
    }
    .rt-tac .rtac-tabs-head {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 48px;
      align-items: start;
      margin-bottom: 52px;
    }
    .rt-tac .rtac-tabs-head h2 {
      font-size: clamp(28px, 3.5vw, 46px);
      font-weight: 950;
      letter-spacing: -0.05em;
      color: #fff;
    }
    .rt-tac .rtac-tabs-head p {
      font-size: 1rem;
      color: var(--rt-muted);
      line-height: 1.65;
      padding-top: 6px;
    }
    .rt-tac .rtac-tabs-grid {
      display: grid;
      grid-template-columns: 260px 1fr;
      gap: 32px;
    }
    .rt-tac .rtac-tab-list {
      display: flex;
      flex-direction: column;
      gap: 6px;
    }
    .rt-tac .rtac-tab-btn {
      padding: 14px 18px;
      border-radius: 12px;
      font-size: 0.92rem;
      font-weight: 700;
      background: transparent;
      border: 1px solid transparent;
      color: var(--rt-muted);
      cursor: pointer;
      text-align: left;
      transition: all 0.2s ease;
      display: flex;
      align-items: center;
      gap: 10px;
      font-family: inherit;
    }
    .rt-tac .rtac-tab-btn.active {
      background: rgba(240, 154, 55, 0.12);
      border-color: rgba(240, 154, 55, 0.28);
      color: var(--rt-orange-2);
    }
    .rt-tac .rtac-tab-panel {
      background: linear-gradient(180deg, #132c48, #0d2138);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 24px;
      padding: 36px;
    }
    .rt-tac .rtac-tab-panel h3 {
      font-size: 1.3rem;
      font-weight: 800;
      margin-bottom: 14px;
      color: #fff;
    }
    .rt-tac .rtac-tab-panel p {
      font-size: 0.95rem;
      color: var(--rt-muted);
      line-height: 1.65;
      margin-bottom: 18px;
    }
    .rt-tac .rtac-check-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 10px;
    }
    .rt-tac .rtac-check {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 0.88rem;
      color: var(--rt-text);
    }
    .rt-tac .rtac-check::before {
      content: "✓";
      width: 20px;
      height: 20px;
      border-radius: 50%;
      background: rgba(240, 154, 55, 0.2);
      color: var(--rt-orange);
      font-size: 0.75rem;
      font-weight: 900;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
    }
    .rt-tac .rtac-profiles {
      padding: 100px 0;
      background:
        radial-gradient(circle at 90% 40%, rgba(240, 154, 55, 0.07), transparent 35%),
        #0a1d31;
    }
    .rt-tac .rtac-profiles-head {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 48px;
      margin-bottom: 52px;
      align-items: start;
    }
    .rt-tac .rtac-profiles-head h2 {
      font-size: clamp(28px, 3.5vw, 46px);
      font-weight: 950;
      letter-spacing: -0.05em;
      color: #fff;
    }
    .rt-tac .rtac-profiles-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 20px;
    }
    .rt-tac .rtac-profile-card {
      background: linear-gradient(180deg, #132c48, #0d2138);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 24px;
      padding: 30px 24px;
      text-align: center;
    }
    .rt-tac .rtac-profile-icon {
      width: 60px;
      height: 60px;
      border-radius: 50%;
      background: rgba(240, 154, 55, 0.18);
      border: 1px solid rgba(240, 154, 55, 0.28);
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 16px;
      font-size: 1.1rem;
      font-weight: 950;
      color: var(--rt-orange);
      letter-spacing: -0.03em;
    }
    .rt-tac .rtac-profile-card h3 {
      font-size: 0.95rem;
      font-weight: 700;
      margin-bottom: 8px;
      color: #fff;
    }
    .rt-tac .rtac-profile-card p {
      font-size: 0.82rem;
      color: var(--rt-muted);
      line-height: 1.55;
    }
    .rt-tac .rtac-flow {
      padding: 100px 0;
      background: #061423;
    }
    .rt-tac .rtac-flow-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 64px;
      align-items: center;
    }
    .rt-tac .rtac-flow-img {
      border-radius: 32px;
      overflow: hidden;
      border: 1px solid rgba(255, 255, 255, 0.08);
      box-shadow: 0 0 40px rgba(240, 154, 55, 0.1);
    }
    .rt-tac .rtac-flow-img img {
      width: 100%;
      display: block;
      height: 360px;
      object-fit: cover;
    }
    .rt-tac .rtac-flow-right h2 {
      font-size: clamp(28px, 3.5vw, 46px);
      font-weight: 950;
      letter-spacing: -0.05em;
      margin-bottom: 16px;
      color: #fff;
    }
    .rt-tac .rtac-flow-right p {
      font-size: 0.95rem;
      color: var(--rt-muted);
      line-height: 1.65;
      margin-bottom: 28px;
    }
    .rt-tac .rtac-chips {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 12px;
    }
    .rt-tac .rtac-chip {
      background: #0d2138;
      border: 1px solid rgba(240, 154, 55, 0.18);
      border-radius: 14px;
      padding: 14px 16px;
      font-size: 0.88rem;
      font-weight: 600;
      display: flex;
      align-items: center;
      gap: 10px;
      color: #fff;
    }
    .rt-tac .rtac-chip-dot {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: var(--rt-orange);
      flex-shrink: 0;
    }
    .rt-tac .rtac-faq {
      padding: 100px 0;
      background: #0a1d31;
    }
    .rt-tac .rtac-faq-head {
      text-align: center;
      margin-bottom: 52px;
    }
    .rt-tac .rtac-faq-head h2 {
      font-size: clamp(28px, 3.5vw, 44px);
      font-weight: 950;
      letter-spacing: -0.05em;
      margin-bottom: 12px;
      color: #fff;
    }
    .rt-tac .rtac-faq-head p {
      font-size: 1rem;
      color: var(--rt-muted);
    }
    .rt-tac .rtac-faq-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 20px;
    }
    .rt-tac .rtac-faq-item {
      background: #0d2138;
      border: 1px solid rgba(255, 255, 255, 0.07);
      border-radius: 20px;
      padding: 28px;
    }
    .rt-tac .rtac-faq-item h3 {
      font-size: 0.98rem;
      font-weight: 700;
      margin-bottom: 10px;
      color: var(--rt-orange-2);
    }
    .rt-tac .rtac-faq-item p {
      font-size: 0.88rem;
      color: var(--rt-muted);
      line-height: 1.65;
    }
    .rt-tac .rtac-related {
      padding: 80px 0;
      background: #061423;
    }
    .rt-tac .rtac-related-head {
      text-align: center;
      margin-bottom: 44px;
    }
    .rt-tac .rtac-related-head h2 {
      font-size: clamp(24px, 3vw, 38px);
      font-weight: 950;
      letter-spacing: -0.04em;
      margin-bottom: 10px;
      color: #fff;
    }
    .rt-tac .rtac-related-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 22px;
    }
    .rt-tac .rtac-rel-card {
      background: linear-gradient(180deg, #132c48, #0d2138);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 22px;
      padding: 28px 24px;
      transition: border-color 0.2s ease, transform 0.2s ease;
    }
    .rt-tac .rtac-rel-card:hover {
      border-color: rgba(240, 154, 55, 0.28);
      transform: translateY(-4px);
    }
    .rt-tac .rtac-rel-icon {
      font-size: 2rem;
      margin-bottom: 14px;
    }
    .rt-tac .rtac-rel-card h3 {
      font-size: 1rem;
      font-weight: 700;
      margin-bottom: 8px;
      color: #fff;
    }
    .rt-tac .rtac-rel-card p {
      font-size: 0.84rem;
      color: var(--rt-muted);
      line-height: 1.55;
      margin-bottom: 14px;
    }
    .rt-tac .rtac-rel-card a {
      font-size: 0.85rem;
      font-weight: 700;
      color: var(--rt-orange);
    }
    @media (max-width: 1100px) {
      .rt-tac .rtac-features {
        grid-template-columns: repeat(2, 1fr);
      }
    }
    @media (max-width: 900px) {
      .rt-tac .rtac-hero-grid,
      .rt-tac .rtac-main-head,
      .rt-tac .rtac-tabs-head,
      .rt-tac .rtac-profiles-head,
      .rt-tac .rtac-flow-grid {
        grid-template-columns: 1fr;
      }
      .rt-tac .rtac-stats-grid,
      .rt-tac .rtac-profiles-grid {
        grid-template-columns: repeat(2, 1fr);
      }
      .rt-tac .rtac-tabs-grid {
        grid-template-columns: 1fr;
      }
      .rt-tac .rtac-related-grid,
      .rt-tac .rtac-faq-grid {
        grid-template-columns: 1fr;
      }
      .rt-tac .rtac-qnav-inner {
        grid-template-columns: 1fr;
      }
      .rt-tac .rtac-qnav-left {
        border-right: 0;
        border-bottom: 1px solid rgba(255, 255, 255, 0.08);
      }
      .rt-tac .rtac-hero-right {
        display: none;
      }
    }
    @media (max-width: 620px) {
      .rt-tac .rtac-wrap {
        padding: 0 20px;
      }
      .rt-tac .rtac-hero {
        min-height: auto;
        padding: 54px 0 76px;
      }
      .rt-tac .rtac-hero h1 {
        font-size: clamp(38px, 13vw, 56px);
      }
      .rt-tac .rtac-hero-btns {
        flex-direction: column;
        align-items: stretch;
      }
      .rt-tac .rtac-btn {
        width: 100%;
      }
      .rt-tac .rtac-features,
      .rt-tac .rtac-stats-grid,
