  <section id="faq" class="rth-faq">
    <div class="rth-wrap">
      <div class="rth-faq-head">
        <div class="rth-eyebrow">Preguntas frecuentes</div>
        <h2>Todo sobre el Sistema HIS Medsi</h2>
