      padding: 8px 14px;
      border-radius: 999px;
      border: 1px solid rgba(240, 154, 55, 0.28);
      background: rgba(240, 154, 55, 0.12);
      color: var(--rt-orange-2);
      font-size: 13px;
      font-weight: 800;
      line-height: 1.25;
      letter-spacing: 0.05em;
      text-transform: uppercase;
    }

    .rt-eyebrow::before {
      content: "";
      width: 8px;
      height: 8px;
      border-radius: 999px;
      background: var(--rt-orange);
      box-shadow: 0 0 18px rgba(240, 154, 55, 0.9);
      flex: 0 0 auto;
    }

    .rt-hero {
      position: relative;
      min-height: 720px;
      padding: 70px 0 86px;
      background:
        radial-gradient(circle at 84% 18%, rgba(240, 154, 55, 0.16), transparent 24%),
        radial-gradient(circle at 18% 20%, rgba(255, 255, 255, 0.05), transparent 30%),
        linear-gradient(135deg, #04111d 0%, #07192b 55%, #091c2f 100%);
      color: var(--rt-white);
      isolation: isolate;
      overflow: hidden;
    }

    .rt-hero::before {
      content: "";
      position: absolute;
      inset: 0;
      background:
        linear-gradient(rgba(255, 255, 255, 0.03) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255, 255, 255, 0.03) 1px, transparent 1px);
      background-size: 42px 42px;
      mask-image: linear-gradient(to bottom, rgba(0, 0, 0, 0.72), transparent);
      z-index: -2;
    }

    .rt-hero::after {
      content: "";
      position: absolute;
      inset: auto -10% -28% -10%;
      height: 360px;
      background: radial-gradient(ellipse at center, rgba(240, 154, 55, 0.12), transparent 64%);
      z-index: -1;
      pointer-events: none;
    }

    .rt-hero-grid {
      display: grid;
      grid-template-columns: minmax(0, 1.02fr) minmax(0, 0.98fr);
      gap: clamp(30px, 4vw, 52px);
      align-items: center;
    }

    .rt-brand {
      width: 220px;
      max-width: 70%;
      margin-bottom: 28px;
      padding: 14px 18px;
      border-radius: 22px;
      background: rgba(255, 255, 255, 0.04);
      border: 1px solid rgba(255, 255, 255, 0.08);
      backdrop-filter: blur(12px);
      box-shadow: 0 18px 45px rgba(0, 0, 0, 0.24);
    }

    .rt-brand img {
      display: block;
      width: 100%;
      height: auto;
    }

    .rt-hero h1 {
      margin: 20px 0 18px;
      max-width: 760px;
      font-size: clamp(42px, 6vw, 76px);
      line-height: 0.96;
      letter-spacing: -0.06em;
      font-weight: 900;
      color: var(--rt-white);
    }

    .rt-hero h1 span {
      display: block;
      background: linear-gradient(90deg, var(--rt-orange), var(--rt-orange-2), #ffffff);
      -webkit-background-clip: text;
      background-clip: text;
      color: transparent;
    }

    .rt-hero p {
      margin: 0;
      max-width: 680px;
      color: rgba(255, 255, 255, 0.82);
      font-size: clamp(18px, 2vw, 22px);
      line-height: 1.58;
    }

    .rt-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 14px;
      margin-top: 30px;
    }

    .rt-btn {
      position: relative;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 10px;
      min-height: 52px;
      padding: 15px 22px;
      border-radius: 999px;
      font-weight: 900;
      overflow: hidden;
      transition: transform 0.25s ease, box-shadow 0.25s ease, background 0.25s ease, border-color 0.25s ease;
      text-align: center;
    }

    .rt-btn::after {
      content: "";
      position: absolute;
      inset: 0;
      background: linear-gradient(100deg, transparent 0%, rgba(255,255,255,.28) 45%, transparent 70%);
      transform: translateX(-120%);
      transition: transform .7s ease;
      pointer-events: none;
    }

    .rt-btn:hover::after {
      transform: translateX(120%);
    }

    .rt-btn:hover {
      transform: translateY(-3px);
    }

    .rt-btn.primary {
      color: #071423;
      background: linear-gradient(135deg, var(--rt-orange), var(--rt-orange-2));
      box-shadow: 0 16px 42px rgba(240, 154, 55, 0.26);
    }

    .rt-btn.secondary {
      color: var(--rt-white);
      border: 1px solid rgba(255, 255, 255, 0.16);
      background: rgba(255, 255, 255, 0.06);
      backdrop-filter: blur(14px);
    }

    .rt-hero-media {
      position: relative;
      min-width: 0;
      perspective: 1000px;
    }

    .rt-hero-orbit {
      position: absolute;
      width: 360px;
      height: 360px;
      right: -42px;
      top: -38px;
      border-radius: 999px;
      border: 1px solid rgba(240, 154, 55, 0.16);
      animation: rtSpin 18s linear infinite;
      pointer-events: none;
      opacity: .75;
    }

    .rt-hero-orbit::before,
    .rt-hero-orbit::after {
      content: "";
      position: absolute;
      border-radius: 999px;
      background: var(--rt-orange);
      box-shadow: 0 0 24px rgba(240,154,55,.75);
    }

    .rt-hero-orbit::before {
      width: 10px;
      height: 10px;
      top: 30px;
      left: 52px;
    }

    .rt-hero-orbit::after {
      width: 7px;
      height: 7px;
      right: 46px;
      bottom: 64px;
    }

    .rt-hero-card {
      position: relative;
      border-radius: 34px;
      overflow: hidden;
      background: rgba(255, 255, 255, 0.03);
      border: 1px solid rgba(255, 255, 255, 0.09);
      box-shadow: 0 30px 90px rgba(0, 0, 0, 0.38), var(--rt-glow);
      transform: rotate(1deg);
      animation: rtFloat 6s ease-in-out infinite;
    }

    .rt-hero-card::before {
      content: "";
      position: absolute;
      inset: 0;
      background: linear-gradient(120deg, rgba(240,154,55,.16), transparent 38%, rgba(255,255,255,.05));
      z-index: 1;
      pointer-events: none;
    }

    .rt-hero-card img {
      display: block;
      width: 100%;
      height: auto;
    }

    .rt-floating {
      position: absolute;
      left: -22px;
      bottom: -28px;
      width: min(360px, 76%);
      padding: 22px;
      border-radius: 26px;
      background: linear-gradient(180deg, #102844 0%, #0b2036 100%);
      color: var(--rt-text);
      border: 1px solid rgba(255, 255, 255, 0.08);
      box-shadow: var(--rt-shadow);
      animation: rtFloatSmall 5s ease-in-out infinite;
    }

    .rt-floating strong {
      display: block;
      font-size: 36px;
      line-height: 1;
      color: var(--rt-orange);
    }

    .rt-floating span {
      display: block;
      margin-top: 6px;
      color: var(--rt-muted);
      font-weight: 700;
      line-height: 1.5;
    }

    .rt-quick {
      margin-top: -52px;
      position: relative;
      z-index: 5;
    }

    .rt-quick-box {
      display: grid;
      grid-template-columns: minmax(0, 0.85fr) minmax(0, 1.15fr);
      gap: 1px;
      border-radius: 30px;
      overflow: hidden;
      background: rgba(255, 255, 255, 0.08);
      box-shadow: var(--rt-shadow);
      border: 1px solid rgba(255,255,255,.08);
    }

    .rt-quick-main {
      padding: 26px;
      background: linear-gradient(180deg, #132c48 0%, #0d2138 100%);
    }

    .rt-quick-main strong {
      display: block;
      color: var(--rt-white);
      font-size: 26px;
      letter-spacing: -0.03em;
      line-height: 1.1;
    }

    .rt-quick-main span {
      display: block;
      margin-top: 8px;
      color: var(--rt-muted);
      line-height: 1.55;
    }

    .rt-quick-links {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 1px;
      background: rgba(255, 255, 255, 0.08);
    }

    .rt-quick-links a {
      min-height: 130px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      padding: 22px;
      background: linear-gradient(180deg, #10243b 0%, #0b1d30 100%);
      transition: background .25s ease, transform .25s ease;
    }

    .rt-quick-links a:hover {
      background: linear-gradient(180deg, #173555 0%, #102844 100%);
    }

    .rt-quick-links b {
      color: var(--rt-white);
      font-size: 18px;
      letter-spacing: -0.02em;
    }

    .rt-quick-links small {
      color: var(--rt-orange-2);
      font-weight: 800;
    }

    .rt-stats {
      padding-top: 34px;
      position: relative;
      z-index: 2;
    }

    .rt-stats-box {
      display: grid;
      grid-template-columns: repeat(5, minmax(0, 1fr));
      gap: 12px;
    }

    .rt-stat {
      padding: 24px 18px;
      border-radius: 24px;
      background: linear-gradient(180deg, #10243b 0%, #0b1d30 100%);
      text-align: center;
      border: 1px solid rgba(255,255,255,.08);
      box-shadow: 0 16px 42px rgba(0,0,0,.16);
    }

    .rt-stat strong {
      display: block;
      font-size: clamp(28px, 3.6vw, 42px);
      line-height: 1;
      color: var(--rt-orange);
      letter-spacing: -0.04em;
    }

    .rt-stat span {
      display: block;
      margin-top: 10px;
      color: var(--rt-muted);
      font-weight: 800;
      font-size: 13px;
      text-transform: uppercase;
      letter-spacing: 0.04em;
    }

    .rt-head {
      display: grid;
      grid-template-columns: minmax(0, 0.82fr) minmax(0, 1.18fr);
      gap: 34px;
      align-items: end;
      margin-bottom: 34px;
    }

    .rt-head h2 {
      margin: 16px 0 0;
      color: var(--rt-white);
      font-size: clamp(34px, 4.5vw, 56px);
      line-height: 1;
      letter-spacing: -0.05em;
      font-weight: 900;
    }

    .rt-head p {
      margin: 0;
      color: #c9d6e6;
      font-size: 18px;
      line-height: 1.68;
    }

    .rt-tabs {
      background:
        radial-gradient(circle at 15% 20%, rgba(240, 154, 55, 0.09), transparent 30%),
        linear-gradient(180deg, var(--rt-bg-2) 0%, var(--rt-bg) 100%);
    }

    .rt-tabs-shell {
      display: grid;
      grid-template-columns: minmax(250px, 300px) minmax(0, 1fr);
      gap: 20px;
      align-items: stretch;
    }

    .rt-tabs-nav {
      display: grid;
      gap: 12px;
      align-content: start;
      min-width: 0;
    }

    .rt-tab-btn {
      width: 100%;
      border: 1px solid rgba(255,255,255,.11) !important;
      border-radius: 22px;
      padding: 17px 18px;
      cursor: pointer;
      text-align: left;
      background: linear-gradient(180deg, #10243b 0%, #0b1d30 100%) !important;
      color: #ffffff !important;
      font-family: inherit;
      box-shadow: 0 14px 34px rgba(0, 0, 0, 0.22) !important;
      transition: transform .25s ease, border-color .25s ease, background .25s ease, box-shadow .25s ease;
    }

    .rt-tab-btn:hover {
      transform: translateX(5px);
      border-color: rgba(240,154,55,.36) !important;
      background: linear-gradient(180deg, #173555 0%, #102844 100%) !important;
    }

    .rt-tab-btn.active {
      transform: translateX(5px);
      border-color: rgba(255,182,92,.8) !important;
      background: linear-gradient(135deg, #f09a37 0%, #ffb65c 100%) !important;
      color: #071423 !important;
      box-shadow: 0 18px 42px rgba(240, 154, 55, 0.28) !important;
    }

    .rt-tab-btn strong {
      display: block;
      color: #ffffff !important;
      font-size: 19px;
      line-height: 1.12;
      letter-spacing: -0.03em;
      font-weight: 900 !important;
    }

    .rt-tab-btn span {
      display: block;
      color: #b8c6d8 !important;
      margin-top: 6px;
      font-size: 13.5px;
      line-height: 1.45;
      font-weight: 700 !important;
    }

    .rt-tab-btn.active strong,
    .rt-tab-btn.active span {
      color: #071423 !important;
    }

    .rt-tab-panel {
      display: none;
      min-height: 500px;
      overflow: hidden;
      border-radius: 34px;
      background: linear-gradient(180deg, var(--rt-card-2) 0%, var(--rt-card) 100%);
      border: 1px solid rgba(255,255,255,.08);
      box-shadow: var(--rt-shadow);
      min-width: 0;
    }

    .rt-tab-panel.active {
      display: grid;
      grid-template-columns: minmax(300px, 0.92fr) minmax(320px, 1.08fr);
      animation: rtFade .45s ease both;
    }

    .rt-tab-media {
      min-height: 500px;
      background: #081522;
      overflow: hidden;
      min-width: 0;
    }

    .rt-tab-media img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      display: block;
      transform: scale(1.02);
    }

    .rt-tab-content {
      min-width: 0;
      padding: clamp(26px, 4vw, 44px);
      display: flex;
      flex-direction: column;
      justify-content: center;
    }

    .rt-tab-content h3 {
      margin: 0 0 14px;
      color: #ffffff !important;
      font-size: clamp(32px, 4vw, 50px);
      line-height: 1;
      letter-spacing: -0.05em;
      font-weight: 900;
      text-shadow: 0 2px 18px rgba(0, 0, 0, 0.28);
    }

    .rt-tab-content p {
      margin: 0;
      color: #c9d6e6 !important;
      font-size: clamp(16px, 1.6vw, 18px);
      line-height: 1.68;
    }

    .rt-checks {
      display: grid;
      grid-template-columns: 1fr;
      gap: 12px;
      margin: 24px 0 0;
      padding: 0;
      list-style: none;
    }

    .rt-checks li {
      position: relative;
      min-height: 54px;
      padding: 14px 16px 14px 48px;
      border-radius: 18px;
      background: rgba(255, 255, 255, 0.065) !important;
      color: #f4f8fc !important;
      font-weight: 800 !important;
      border: 1px solid rgba(255, 255, 255, 0.09) !important;
      word-break: normal !important;
      overflow-wrap: normal !important;
      hyphens: none !important;
      line-height: 1.45;
    }

    .rt-checks li::before {
      content: "✓";
      position: absolute;
      left: 16px;
      top: 14px;
      width: 24px;
      height: 24px;
      border-radius: 50%;
      display: grid;
      place-items: center;
      background: linear-gradient(135deg, #f09a37, #ffb65c) !important;
      color: #071423 !important;
      font-size: 14px;
      font-weight: 900;
    }

    .rt-specialty {
      background:
        radial-gradient(circle at 80% 20%, rgba(240, 154, 55, 0.13), transparent 28%),
        linear-gradient(135deg, #04111d 0%, #0a1f34 100%);
      color: var(--rt-white);
    }

    .rt-special-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 18px;
    }

    .rt-special-card {
      position: relative;
      min-height: 230px;
      padding: 28px;
      border-radius: 30px;
      border: 1px solid rgba(255, 255, 255, 0.08);
      background: rgba(255, 255, 255, 0.05);
      backdrop-filter: blur(14px);
      transition: transform 0.25s ease, border-color 0.25s ease, box-shadow 0.25s ease;
      overflow: hidden;
    }

    .rt-special-card::before {
      content: "";
      position: absolute;
      inset: -1px;
      background: linear-gradient(135deg, rgba(240,154,55,.18), transparent 42%);
      opacity: 0;
      transition: opacity .25s ease;
      pointer-events: none;
    }

    .rt-special-card:hover {
      transform: translateY(-5px);
      border-color: rgba(240, 154, 55, 0.22);
      box-shadow: 0 20px 50px rgba(0, 0, 0, 0.22);
    }

    .rt-special-card:hover::before {
      opacity: 1;
    }

    .rt-special-card h3,
    .rt-special-card p,
    .rt-special-card a {
      position: relative;
      z-index: 1;
    }

    .rt-special-card h3 {
      margin: 0 0 14px;
      font-size: 25px;
      line-height: 1.12;
      letter-spacing: -0.03em;
      color: var(--rt-white);
    }

    .rt-special-card p {
      margin: 0;
      color: rgba(255, 255, 255, 0.78);
      line-height: 1.65;
    }

    .rt-link {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      margin-top: 20px;
      color: var(--rt-orange-2);
      font-weight: 900;
    }

    .rt-link::after {
      content: "→";
      transition: transform 0.2s ease;
    }

    .rt-special-card:hover .rt-link::after {
      transform: translateX(4px);
    }

    .rt-proof {
      background: var(--rt-bg);
    }

    .rt-proof-grid {
      display: grid;
      grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.1fr);
      gap: 24px;
      align-items: stretch;
    }

    .rt-proof-card {
      padding: clamp(28px, 4vw, 46px);
      border-radius: 34px;
      background: linear-gradient(180deg, var(--rt-card-2) 0%, var(--rt-card) 100%);
      border: 1px solid rgba(255,255,255,.08);
      box-shadow: 0 18px 55px rgba(0,0,0,.2);
    }

    .rt-proof-card h2 {
      margin: 14px 0 16px;
      color: var(--rt-white);
      font-size: clamp(34px, 4.2vw, 54px);
      line-height: 1;
      letter-spacing: -0.05em;
      font-weight: 900;
    }

    .rt-proof-card p {
      margin: 0;
      color: var(--rt-muted);
      font-size: 18px;
      line-height: 1.7;
    }

    .rt-quotes-stack {
      display: grid;
      gap: 14px;
    }

    .rt-quote {
      padding: 24px;
      border-radius: 26px;
      background: linear-gradient(180deg, #10243b 0%, #0b1d30 100%);
      border: 1px solid rgba(255, 255, 255, 0.08);
      box-shadow: 0 16px 45px rgba(0, 0, 0, 0.18);
    }

    .rt-quote p {
      margin: 0;
      color: var(--rt-text);
      line-height: 1.65;
    }

    .rt-quote strong {
      display: block;
      margin-top: 16px;
      color: var(--rt-white);
      font-size: 17px;
    }

    .rt-quote span {
      display: block;
      margin-top: 4px;
      color: var(--rt-orange);
      font-weight: 800;
      font-size: 14px;
    }

    .rt-cta {
      padding: 76px 0;
      background:
        radial-gradient(circle at 20% 20%, rgba(240, 154, 55, 0.16), transparent 26%),
        linear-gradient(135deg, #04111d 0%, #091d31 100%);
      color: var(--rt-white);
    }

    .rt-cta-box {
      display: grid;
      grid-template-columns: minmax(0, 1fr) auto;
      gap: 32px;
      align-items: center;
      padding: clamp(30px, 5vw, 56px);
      border-radius: 36px;
      border: 1px solid rgba(255, 255, 255, 0.08);
      background: rgba(255, 255, 255, 0.05);
      box-shadow: 0 24px 70px rgba(0, 0, 0, 0.22);
      backdrop-filter: blur(12px);
    }

    .rt-cta h2 {
      margin: 0 0 14px;
      font-size: clamp(34px, 4.5vw, 60px);
      line-height: 1;
      letter-spacing: -0.05em;
      font-weight: 900;
      color: var(--rt-white);
    }

    .rt-cta p {
      margin: 0;
      color: rgba(255, 255, 255, 0.78);
      font-size: 18px;
      line-height: 1.7;
    }

    @keyframes rtFloat {
      0%, 100% { transform: rotate(1deg) translateY(0); }
      50% { transform: rotate(1deg) translateY(-14px); }
    }

    @keyframes rtFloatSmall {
      0%, 100% { transform: translateY(0); }
      50% { transform: translateY(-8px); }
    }

    @keyframes rtSpin {
      to { transform: rotate(360deg); }
    }

    @keyframes rtFade {
      from { opacity: 0; transform: translateY(12px); }
      to { opacity: 1; transform: translateY(0); }
    }

    @media (max-width: 1280px) {
      .rt-tabs-shell {
        grid-template-columns: minmax(235px, 290px) minmax(0, 1fr);
        gap: 18px;
      }

      .rt-tab-panel.active {
        grid-template-columns: minmax(260px, 0.85fr) minmax(300px, 1.15fr);
      }

      .rt-tab-content {
        padding: 30px;
      }

      .rt-tab-btn {
        padding: 16px;
      }

      .rt-tab-btn strong {
        font-size: 18px;
      }

      .rt-tab-btn span {
        font-size: 13px;
      }
    }

    @media (max-width: 1100px) {
      .rt-tabs-shell {
        grid-template-columns: 1fr;
      }

      .rt-tabs-nav {
        grid-template-columns: repeat(5, minmax(150px, 1fr));
        overflow-x: auto;
        padding-bottom: 8px;
        scroll-snap-type: x proximity;
      }

      .rt-tab-btn {
        min-width: 160px;
        scroll-snap-align: start;
      }

      .rt-tab-btn:hover,
      .rt-tab-btn.active {
        transform: translateY(-2px);
      }

      .rt-tab-panel.active {
        grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr);
      }

      .rt-checks {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }
    }

    @media (max-width: 980px) {
      .rt-hero {
        min-height: auto;
        padding: 54px 0 90px;
      }

      .rt-hero-grid,
      .rt-head,
      .rt-tab-panel.active,
      .rt-proof-grid,
      .rt-cta-box,
      .rt-quick-box {
        grid-template-columns: 1fr;
      }

      .rt-quick-links {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      .rt-stats-box {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      .rt-special-grid {
        grid-template-columns: 1fr;
      }

      .rt-special-card {
        min-height: auto;
      }

      .rt-tab-media {
        min-height: 320px;
      }

      .rt-checks {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      .rt-cta-box {
        text-align: left;
      }
    }

    @media (max-width: 760px) {
